array-128-1.kujo.source:
func update(input, index) { mut result := input result[index] = index + 1 return result }

let size := 128
mut values := [] mut k := 0 while k < size { values = push(values, 0) k += 1 }
mut data := values
values = []
mut saved := []

env_set("KUJO_ALLOCATION_PHASE", "4")
mut i := 0
while i < 1 {

  data[i] = i + 1
  if (data[i]) != (i + 1) { assert_equal(data[i], i + 1) }

  i += 1
}
env_set("KUJO_ALLOCATION_PHASE", "5")
print("ISOLATION PASS array unique 128")

